import {calcDamage,clamp} from './model.mjs';
export function duelRound(b,chart,random=Math.random){if(!b.teams.every(t=>b.actions[t.pid]))return null;const events=[];for(const t of b.teams){const a=b.actions[t.pid];if(a.swap!==undefined&&t.mons[a.swap]?.hp>0){t.active=a.swap;events.push({kind:'swap',pid:t.pid,key:t.mons[t.active].key})}}const order=b.teams.filter(t=>b.actions[t.pid].move!==undefined).map(t=>({pid:t.pid,slot:t.active,speed:t.mons[t.active].speed})).sort((a,b)=>b.speed-a.speed);for(const turn of order){const t=b.teams.find(t=>t.pid===turn.pid),enemy=b.teams.find(e=>e.pid!==turn.pid),source=t.mons[t.active],target=enemy.mons[enemy.active];if(t.active!==turn.slot||source.hp<=0||target.hp<=0)continue;const m=source.moves[b.actions[t.pid].move];if(!m||m.left<=0)continue;m.left--;const r=calcDamage(source,target,m,chart,random);target.hp=Math.max(0,target.hp-r.n);events.push({kind:'attack',source:t.pid,target:enemy.pid,sourceKey:source.key,targetKey:target.key,move:m.name,type:m.type,amount:r.n,text:r.text,hp:target.hp,max:target.max});if(!target.hp){events.push({kind:'ko',pid:enemy.pid,key:target.key});const next=enemy.mons.findIndex(p=>p.hp>0);if(next>=0){enemy.active=next;events.push({kind:'swap',pid:enemy.pid,key:enemy.mons[next].key})}}}for(const t of b.teams){const p=t.mons[t.active];if(p.moves.every(m=>m.left<=0))p.moves=[{id:0,name:'Lutte',type:'normal',power:50,accuracy:100,special:false,pp:999,left:999}]}b.actions={};b.turn++;b.over=b.teams.some(t=>!t.mons.some(m=>m.hp>0));b.winner=b.over?b.teams.find(t=>t.mons.some(m=>m.hp>0))?.pid:null;return events}
